const listAccountCards = `-- name: ListAccountCards :many
SELECT 
    c.id, c.uuid, c.user_id, c.name, c.card_uid, c.activation_code, c.smart_code, c.target_type, c.profile_id, c.direct_url, c.custom_data, c.card_type, c.material, c.color_hex, c.is_active, c.is_locked, c.lead_capture_enabled, c.passcode, c.created_at, c.updated_at, c.deleted_at, c.order_id, c.order_item_id, c.status, c.account_id,
    p.uuid as profile_uuid,
    p.avatar_url as profile_avatar_url,
    p.primary_locale as profile_primary_locale,
    -- Card scans are analytics events of this route (subject {type: route, id: route_uuid}).
    (SELECT r.uuid FROM routes r
     WHERE r.card_id = c.id AND r.route_type = 'card_route' AND r.deleted_at IS NULL
     LIMIT 1) AS route_uuid
FROM nfc_cards c
LEFT JOIN profiles p ON p.id = c.profile_id AND p.deleted_at IS NULL
WHERE c.account_id = $1
  AND c.deleted_at IS NULL
  AND (
    $2::text IS NULL
    OR c.name ILIKE '%' || $2 || '%'
    OR c.smart_code ILIKE '%' || $2 || '%'
    OR c.card_uid ILIKE '%' || $2 || '%'
  )
  AND (
    $3::boolean IS NULL
    OR c.is_active = $3::boolean
  )
ORDER BY c.created_at DESC
LIMIT $5 OFFSET $4
`

type ListAccountCardsParams struct {
	AccountID   int64       `json:"account_id"`
	Q           pgtype.Text `json:"q"`
	IsActive    pgtype.Bool `json:"is_active"`
	OffsetCount int32       `json:"offset_count"`
	LimitCount  int32       `json:"limit_count"`
}

type ListAccountCardsRow struct {
	ID                   int64              `json:"id"`
	Uuid                 uuid.UUID          `json:"uuid"`
	UserID               int64              `json:"user_id"`
	Name                 string             `json:"name"`
	CardUid              pgtype.Text        `json:"card_uid"`
	ActivationCode       pgtype.Text        `json:"activation_code"`
	SmartCode            string             `json:"smart_code"`
	TargetType           string             `json:"target_type"`
	ProfileID            pgtype.Int8        `json:"profile_id"`
	DirectUrl            string             `json:"direct_url"`
	CustomData           []byte             `json:"custom_data"`
	CardType             string             `json:"card_type"`
	Material             string             `json:"material"`
	ColorHex             string             `json:"color_hex"`
	IsActive             bool               `json:"is_active"`
	IsLocked             bool               `json:"is_locked"`
	LeadCaptureEnabled   bool               `json:"lead_capture_enabled"`
	Passcode             pgtype.Text        `json:"passcode"`
	CreatedAt            pgtype.Timestamptz `json:"created_at"`
	UpdatedAt            pgtype.Timestamptz `json:"updated_at"`
	DeletedAt            pgtype.Timestamptz `json:"deleted_at"`
	OrderID              pgtype.Int8        `json:"order_id"`
	OrderItemID          pgtype.Int8        `json:"order_item_id"`
	Status               string             `json:"status"`
	AccountID            int64              `json:"account_id"`
	ProfileUuid          pgtype.UUID        `json:"profile_uuid"`
	ProfileAvatarUrl     pgtype.Text        `json:"profile_avatar_url"`
	ProfilePrimaryLocale pgtype.Text        `json:"profile_primary_locale"`
	RouteUuid            uuid.UUID          `json:"route_uuid"`
}

// account-lint: cross-account card-route subquery is keyed by this account's card id (display only)
func (q *Queries) ListAccountCards(ctx context.Context, arg ListAccountCardsParams) ([]ListAccountCardsRow, error) {
	rows, err := q.db.Query(ctx, listAccountCards,
		arg.AccountID,
		arg.Q,
		arg.IsActive,
		arg.OffsetCount,
		arg.LimitCount,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListAccountCardsRow{}
	for rows.Next() {
		var i ListAccountCardsRow
		if err := rows.Scan(
			&i.ID,
			&i.Uuid,
			&i.UserID,
			&i.Name,
			&i.CardUid,
			&i.ActivationCode,
			&i.SmartCode,
			&i.TargetType,
			&i.ProfileID,
			&i.DirectUrl,
			&i.CustomData,
			&i.CardType,
			&i.Material,
			&i.ColorHex,
			&i.IsActive,
			&i.IsLocked,
			&i.LeadCaptureEnabled,
			&i.Passcode,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.DeletedAt,
			&i.OrderID,
			&i.OrderItemID,
			&i.Status,
			&i.AccountID,
			&i.ProfileUuid,
			&i.ProfileAvatarUrl,
			&i.ProfilePrimaryLocale,
			&i.RouteUuid,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const toggleCardLock = `-- name: ToggleCardLock :one
UPDATE nfc_cards
SET is_locked = NOT is_locked
WHERE uuid = $1
  AND account_id = $2
  AND deleted_at IS NULL
RETURNING is_locked
`

type ToggleCardLockParams struct {
	Uuid      uuid.UUID `json:"uuid"`
	AccountID int64     `json:"account_id"`
}

func (q *Queries) ToggleCardLock(ctx context.Context, arg ToggleCardLockParams) (bool, error) {
	row := q.db.QueryRow(ctx, toggleCardLock, arg.Uuid, arg.AccountID)
	var is_locked bool
	err := row.Scan(&is_locked)
	return is_locked, err
}

const updateCard = `-- name: UpdateCard :one
UPDATE nfc_cards
SET 
    name = COALESCE($1, name),
    target_type = COALESCE($2, target_type),
    profile_id = CASE WHEN $3::boolean THEN $4 ELSE profile_id END,
    direct_url = COALESCE($5, direct_url),
    custom_data = COALESCE($6, custom_data),
    card_type = COALESCE($7, card_type),
    material = COALESCE($8, material),
    color_hex = COALESCE($9, color_hex),
    is_active = COALESCE($10, is_active),
    is_locked = COALESCE($11, is_locked),
    lead_capture_enabled = COALESCE($12, lead_capture_enabled),
    passcode = CASE WHEN $13::boolean THEN $14 ELSE passcode END
WHERE uuid = $15
  AND account_id = $16
  AND deleted_at IS NULL
RETURNING id, uuid, user_id, name, card_uid, activation_code, smart_code, target_type, profile_id, direct_url, custom_data, card_type, material, color_hex, is_active, is_locked, lead_capture_enabled, passcode, created_at, updated_at, deleted_at, order_id, order_item_id, status, account_id
`

type UpdateCardParams struct {
	Name               pgtype.Text `json:"name"`
	TargetType         pgtype.Text `json:"target_type"`
	SetProfileID       bool        `json:"set_profile_id"`
	ProfileID          pgtype.Int8 `json:"profile_id"`
	DirectUrl          pgtype.Text `json:"direct_url"`
	CustomData         []byte      `json:"custom_data"`
	CardType           pgtype.Text `json:"card_type"`
	Material           pgtype.Text `json:"material"`
	ColorHex           pgtype.Text `json:"color_hex"`
	IsActive           pgtype.Bool `json:"is_active"`
	IsLocked           pgtype.Bool `json:"is_locked"`
	LeadCaptureEnabled pgtype.Bool `json:"lead_capture_enabled"`
	SetPasscode        bool        `json:"set_passcode"`
	Passcode           pgtype.Text `json:"passcode"`
	Uuid               uuid.UUID   `json:"uuid"`
	AccountID          int64       `json:"account_id"`
}

func (q *Queries) UpdateCard(ctx context.Context, arg UpdateCardParams) (NfcCard, error) {
	row := q.db.QueryRow(ctx, updateCard,
		arg.Name,
		arg.TargetType,
		arg.SetProfileID,
		arg.ProfileID,
		arg.DirectUrl,
		arg.CustomData,
		arg.CardType,
		arg.Material,
		arg.ColorHex,
		arg.IsActive,
		arg.IsLocked,
		arg.LeadCaptureEnabled,
		arg.SetPasscode,
		arg.Passcode,
		arg.Uuid,
		arg.AccountID,
	)
	var i NfcCard
	err := row.Scan(
		&i.ID,
		&i.Uuid,
		&i.UserID,
		&i.Name,
		&i.CardUid,
		&i.ActivationCode,
		&i.SmartCode,
		&i.TargetType,
		&i.ProfileID,
		&i.DirectUrl,
		&i.CustomData,
		&i.CardType,
		&i.Material,
		&i.ColorHex,
		&i.IsActive,
		&i.IsLocked,
		&i.LeadCaptureEnabled,
		&i.Passcode,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
		&i.OrderID,
		&i.OrderItemID,
		&i.Status,
		&i.AccountID,
	)
	return i, err
}
